import React, { useRef, useState } from "react";
import {
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  sendEmailVerification
} from "firebase/auth";
import { auth } from "../firebase"; // Import the auth object from your Firebase setup
import "../styles/Login.css";
import Button from "./Button";
import Spinner from "./Spinner";
import { useNavigate } from "react-router-dom";

function Login() {
  const userRef = useRef<HTMLInputElement | null>(null);
  const pwRef = useRef<HTMLInputElement | null>(null);
  const [isLogin, setIsLogin] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleLoginSubmit = async () => {
    setIsLoading(true);
    setError(null);
    const username = userRef.current?.value || "";
    const pw = pwRef.current?.value || "";

    try {
      const userCredential = await signInWithEmailAndPassword(auth, username, pw);
      const user = userCredential.user;
      navigate("/home");
    } catch (err) {
      console.log(err);
      setError(
        "Failed to log in. Please check your credentials and try again."
      );
    }
    return;
  };

  const handleSignupSubmit = async () => {
    setIsLoading(true);
    setError(null);
    const username = userRef.current?.value || "";
    const pw = pwRef.current?.value || "";

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, username, pw);
      const user = userCredential.user;

      // Send email verification
      await sendEmailVerification(user);

      setIsLogin(true);
      alert("Sign up successful! Please check your email to verify your account before logging in.");
    } catch (err) {
      console.log(err);
      setError(
        "Failed to sign up. Please check your credentials and try again."
      );
    }
    return;
  };

  const toggleAuthMode = () => {
    setIsLogin(!isLogin);
  };

  return (
    <div className="login">
      <h1>Welcome to MLB Match Maker!</h1>
      {/* <p>Please {isLogin ? "log in" : "sign up"} below</p> */}
      <form onSubmit={(e) => e.preventDefault}>
        <label>Email:</label>
        <input type="text" ref={userRef} />
        <label>Password:</label>
        <input type="text" ref={pwRef} />
      </form>
      {error && <div style={{ color: "red" }}>{error}</div>}
      <Button onClick={isLogin ? handleLoginSubmit : handleSignupSubmit}>
        {isLoading ? <Spinner size={30} /> : "Submit"}
      </Button>
      <p>
        {isLogin ? (
          <span
            onClick={toggleAuthMode}
            style={{
              cursor: "pointer",
              fontSize: ".8rem",
              textDecoration: "underline",
            }}
          >
            Don't have an account? Sign up
          </span>
        ) : (
          <span
            onClick={toggleAuthMode}
            style={{
              cursor: "pointer",
              fontSize: ".8rem",
              textDecoration: "underline",
            }}
          >
            Have an account? Login
          </span>
        )}
      </p>
    </div>
  );
}

export default Login;
